mapper.select:
SELECT `smt`.`id`, `smt`.`name`, `smt`.`content`, `smt`.`channel_code`, `smt`.`enabled`, `smt`.`msg_scene_code`, `smt`.`msg_scene_name`, `smt`.`application_code`, `smt`.`application_name`, smtm.`manufacturer_tmp_config` as `config` FROM `sat_msg_tmp` `smt` left JOIN `sat_msg_tmp_manufacturer` `smtm` on `smt`.`id` = `smtm`.`sat_msg_tmp_id`
`smt`.`channel_code` = #{param.channelCode}
and `smt`.`name` like concat('%',#{param.keyword},'%')
and `smt`.`application_code` = #{param.applicationCode}
and `smt`.`channel_code` = #{param.channelCode}
and `smt`.`enabled` = #{param.enabled}
order by `smt`.`create_time` desc

SELECT `smt`.`id`, `smt`.`name`, `smt`.`content`, `smt`.`channel_code`, `smt`.`enabled`, `smt`.`msg_scene_code`, `smt`.`msg_scene_name`, `smt`.`application_code`, `smt`.`application_name`, `smtm`.`manufacturer_tmp_config` as `config` FROM `sat_msg_tmp` `smt` left JOIN `sat_msg_tmp_manufacturer` `smtm` on `smt`.`id` = `smtm`.`sat_msg_tmp_id`
`smt`.`channel_code` = #{param.channelCode}
and `smt`.`name` like concat('%',#{param.keyword},'%')
and `smt`.`application_code` = #{param.applicationCode}
and `smt`.`msg_scene_code` = #{param.sceneCode}
and `smt`.`channel_code` = #{param.channelCode}
and `smt`.`enabled` = #{param.enabled}
order by `smt`.`create_time` desc
